def fizzbuzz(limit):
    """Return the FizzBuzz sequence from 1 to limit."""
    results = []
    for number in range(1, limit + 1):
        if number % 15 == 0:
            results.append("FizzBuzz")
        elif number % 3 == 0:
            results.append("Fizz")
        elif number % 5 == 0:
            results.append("Buzz")
        else:
            results.append(str(number))
    return results


def main():
    """Print FizzBuzz up to 100, one value per line."""
    values = fizzbuzz(100)
    for value in values:
        print(value)
    print(f"Printed {len(values)} values.")
    fizz_count = values.count("Fizz")
    print(f"Fizz appeared {fizz_count} times.")


if __name__ == "__main__":
    main()

import time
from functools import lru_cache


@lru_cache(maxsize=None)
def fibonacci(n):
    """Return the n-th Fibonacci number."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)


def main():
    start = time.perf_counter()
    numbers = [fibonacci(i) for i in range(35)]
    elapsed = time.perf_counter() - start
    print("The first 35 Fibonacci numbers:")
    for index, value in enumerate(numbers):
        print(f"F({index}) = {value}")
    print(f"Sum: {sum(numbers)}")
    print(f"Largest value: {numbers[-1]}")
    print(f"Ratio of last two: {numbers[-1] / numbers[-2]:.3f}")
    print(f"Computed in {elapsed:.4f} seconds.")


if __name__ == "__main__":
    main()

def count_words(text):
    """Count how often each word appears in the text."""
    counts = {}
    for word in text.lower().split():
        word = word.strip(".,;:!?")
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts


def main():
    text = "the quick brown fox jumps over the lazy dog, and the dog barks"
    counts = count_words(text)
    ranked = sorted(counts.items(), key=lambda item: item[1], reverse=True)
    print("Word frequencies:")
    for word, count in ranked:
        print(f"{word:>10}: {count}")
    print(f"Distinct words: {len(counts)}")
    print(f"Most common word: {ranked[0][0]}")


if __name__ == "__main__":
    main()

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance
        self.history = []

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Amount must be positive")
        self.balance += amount
        self.history.append(f"+{amount}")

    def withdraw(self, amount):
        if amount > self.balance:
            print("Insufficient funds")
            return False
        self.balance -= amount
        self.history.append(f"-{amount}")
        return True

    def statement(self):
        print(f"Account of {self.owner}")
        for entry in self.history:
            print(f"  {entry}")
        print(f"Balance: {self.balance}")


def main():
    account = BankAccount("Ada", 100)
    account.deposit(50)
    account.withdraw(30)
    account.withdraw(500)
    account.statement()


if __name__ == "__main__":
    main()

import random


def play_round(secret, attempts):
    """Return the number of guesses needed, or None if failed."""
    for attempt in range(1, attempts + 1):
        guess = random.randint(1, 100)
        if guess == secret:
            return attempt
    return None


def main():
    random.seed(42)
    wins = 0
    rounds = 10
    for game in range(rounds):
        secret = random.randint(1, 100)
        result = play_round(secret, 7)
        if result is not None:
            wins += 1
            print(f"Game {game + 1}: found {secret} in {result} tries")
        else:
            print(f"Game {game + 1}: lost, secret was {secret}")
    print(f"Won {wins}/{rounds} games")


if __name__ == "__main__":
    main()

def is_prime(n):
    if n < 2:
        return False
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 1
    return True


for number in range(2, 20):
    if is_prime(number):
        print(f"{number} is prime")

