def parse_scores(raw):
    """Parse 'name:score' lines into a dictionary."""
    scores = {}
    for line in raw.strip().splitlines():
        name, value = line.split(":")
        scores[name.strip()] = int(value.strip())
    return scores


def main():
    raw = "ada: 15\nbob: 9\neve: 18\nmax: 12"
    scores = parse_scores(raw)
    best = max(scores, key=scores.get)
    worst = min(scores, key=scores.get)
    average = sum(scores.values()) / len(scores)
    print(f"Best score: {best}")
    print(f"Worst score: {worst}")
    print(f"Average: {average:.1f}")
    for name, score in sorted(scores.items()):
        print(f"{name:>5}: {score}")


if __name__ == "__main__":
    main()

class ContactBook:
    def __init__(self):
        self.contacts = {}

    def add(self, name, email):
        if name in self.contacts:
            print(f"{name} already exists")
            return False
        self.contacts[name] = email
        return True

    def find(self, name):
        return self.contacts.get(name, "not found")

    def remove(self, name):
        if name in self.contacts:
            del self.contacts[name]
            return True
        return False

    def show_all(self):
        for name, email in sorted(self.contacts.items()):
            print(f"{name:>10}: {email}")


def main():
    book = ContactBook()
    book.add("ada", "ada@example.com")
    book.add("bob", "bob@example.com")
    book.add("ada", "duplicate@example.com")
    print(book.find("ada"))
    print(book.find("eve"))
    book.show_all()
    book.remove("bob")
    print(f"Remaining: {len(book.contacts)}")


if __name__ == "__main__":
    main()
